class Solution {
    public int maxSumDivThree(int[] nums){
        int negative=Integer.MIN_VALUE/4;
        int[] dp={
            0,negative,negative
        };
        for(int value:nums){
            int[] next=dp.clone();
            for(int remainder=0;remainder<3;remainder++)if(dp[remainder]>negative)next[(dp[remainder]+value)%3]=Math.max(next[(dp[remainder]+value)%3],dp[remainder]+value);
            dp=next;
        }
        return dp[0];
    }
}

code.kotlin:
class Solution {
    fun maxSumDivThree(nums:IntArray):Int{
        val negative=Int.MIN_VALUE/4;
        var dp=intArrayOf(0,negative,negative);
        for(value in nums){
            val next=dp.copyOf();
            for(remainder in 0..2)if(dp[remainder]>negative){
                val candidate=dp[remainder]+value;
                next[candidate%3]=maxOf(next[candidate%3],candidate)
            };
            dp=next
        };
        return dp[0]
    }
}

code.cpp:
class Solution {
    public: int maxSumDivThree(vector<int>& nums){
        const int negative=INT_MIN/4;
        array<int,3> dp{
            0,negative,negative
        };
        for(int value:nums){
            auto next=dp;
            for(int remainder=0;remainder<3;++remainder)if(dp[remainder]>negative){
                int candidate=dp[remainder]+value;
                next[candidate%3]=max(next[candidate%3],candidate);
            }
            dp=next;
        }
        return dp[0];
    }
};
